"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { CopyButton } from "@/components/ui/copy-button";

export interface CodeBlockProps extends Omit<React.ComponentProps<"figure">, "children"> {
  /** The exact source. It is what the copy button writes. */
  code: string;
  /** Shown in the caption bar, such as "tsx" or "bash". */
  language?: string;
  /** Shown in the caption bar and used to name the scroll region. */
  filename?: string;
  /** Show the copy button. */
  copyable?: boolean;
  /** Number the lines. Numbers are generated by CSS and never copied. */
  showLineNumbers?: boolean;
  /** Caps the height and scrolls, for long files. */
  maxHeight?: number | string;
  /** Accessible name of the copy button. */
  copyLabel?: string;
}

/**
 * A captioned code sample with a copy button. The scroll region is focusable
 * so a keyboard can scroll a long line, and it has a name. No highlighter is
 * bundled; the block renders plain text so it stays light and safe.
 */
function CodeBlock({
  code,
  language,
  filename,
  copyable = true,
  showLineNumbers = false,
  maxHeight,
  copyLabel = "Copy code",
  className,
  ...props
}: CodeBlockProps) {
  const lines = React.useMemo(() => code.replace(/\n$/, "").split("\n"), [code]);
  const hasCaption = Boolean(filename || language || copyable);

  return (
    <figure
      data-slot="code-block"
      className={cn("min-w-0 overflow-hidden border border-border bg-muted/30", className)}
      {...props}
    >
      {hasCaption ? (
        <figcaption className="flex min-h-10 items-center justify-between gap-3 border-b border-border bg-muted px-4 py-1.5">
          <span className="flex min-w-0 items-center gap-3">
            {filename ? (
              <span className="truncate font-mono text-xs text-foreground">{filename}</span>
            ) : null}
            {language ? (
              <span className="shrink-0 text-[10px] font-bold uppercase tracking-[0.12em] text-muted-foreground">
                {language}
              </span>
            ) : null}
          </span>
          {copyable ? <CopyButton value={code} label={copyLabel} /> : null}
        </figcaption>
      ) : null}
      <pre
        tabIndex={0}
        aria-label={filename ? `${filename} source` : "Code sample"}
        className="overflow-auto p-4 text-[13px] leading-relaxed text-foreground outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-focus-ring"
        style={maxHeight !== undefined ? { maxHeight } : undefined}
      >
        <code className={cn("font-mono", showLineNumbers && "grid [counter-reset:line]")}>
          {showLineNumbers
            ? lines.map((line, index) => (
                <span
                  key={index}
                  className="[counter-increment:line] before:mr-4 before:inline-block before:w-6 before:select-none before:text-right before:text-muted-foreground before:content-[counter(line)]"
                >
                  {line || " "}
                </span>
              ))
            : code}
        </code>
      </pre>
    </figure>
  );
}

export { CodeBlock };
